# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: step2-seed-routes.sh

REGION=ap-south-2
TABLE=routing-table
MOCK=http://mock-bank-server.ibts-app.svc.cluster.local:8080/mock

while IFS='|' read -r code name; do
  p=$(echo "$code" | tr 'A-Z' 'a-z')
  aws dynamodb put-item --region "$REGION" --table-name "$TABLE" --item "{
    \"bankCode\":         {\"S\": \"$code\"},
    \"bankName\":         {\"S\": \"$name\"},
    \"primaryEndpoint\":  {\"S\": \"$MOCK/$p/txn\"},
    \"fallbackEndpoint\": {\"S\": \"$MOCK/$p/txn/fallback\"},
    \"active\":           {\"BOOL\": true},
    \"updatedAt\":        {\"N\": \"$(date +%s%3N)\"}
  }" && echo "seeded $code"
done <<'EOF'
SBI|State Bank of India
ICICI|ICICI Bank
HDFC|HDFC Bank
AXIS|Axis Bank
YESBANK|Yes Bank
PAYTM|Paytm Payments Bank
KOTAK|Kotak Mahindra Bank
INDUSIND|IndusInd Bank
PNB|Punjab National Bank
BOI|Bank of India
CANARA|Canara Bank
FEDERAL|Federal Bank
NPCI|NPCI Default
EOF

aws dynamodb scan --table-name "$TABLE" --region "$REGION" --select COUNT   # expect Count: 13